  ('article-e2axxm3i', 'feed-openai', 'OpenAI News', 'Introducing the Adoption news channel', 'https://openai.com/index/introducing-the-adoption-news-channel', 'AI', '2026-03-05T00:00:00.000Z'::timestamptz, '2026-03-08T15:11:45.441Z'::timestamptz, 'Practical insights and frameworks to turn AI progress into business advantage', 'Practical insights and frameworks to turn AI progress into business advantage'),
